class PriceEngine:
    DISCOUNT_PRO = 0.90

    @staticmethod
    def price(plan, amount):
        """
        Calculate the price based on the plan and apply discount if necessary.

        Args:
        plan (str): The plan type ('basic' or 'pro').
        amount (float): The original amount before applying any discounts.

        Returns:
        float: The final price after applying the discount, rounded to 2 decimal places.

        Raises:
        KeyError: If the plan is not recognized.
        """
        if plan == 'basic':
            return round(amount, 2)
        elif plan == 'pro':
            discounted_amount = amount * PriceEngine.DISCOUNT_PRO
            return round(discounted_amount, 2)
        else:
            raise KeyError(f"Unknown plan: {plan}")

class PriceEngine:
    DISCOUNT_PRO = 0.90

    @staticmethod
    def price(plan, amount):
        """
        Calculates the price based on the plan type.

        :param plan: str, the plan type ('basic' or 'pro')
        :param amount: float, the original amount before discount
        :return: float, the final price rounded to 2 decimal places
        :raises KeyError: if the plan is not recognized
        """
        if plan == 'basic':
            return round(amount, 2)
        elif plan == 'pro':
            discounted_amount = amount * PriceEngine.DISCOUNT_PRO
            return round(discounted_amount, 2)
        else:
            raise KeyError(f"Unknown plan: {plan}")

class FeatureFlags:
    def __init__(self):
        self.flags = {}
        self.search = False
        self.export = False

    def set(self, name, enabled):
        if name in ('search', 'export'):
            raise ValueError(f"Flag '{name}' is reserved and cannot be changed.")
        self.flags[name] = enabled

    def get(self, name):
        return self.flags.get(name, False)

class FeatureFlags:
    def __init__(self):
        self.flags = {}
        self.search = False
        self.export = False

    def set(self, name, enabled):
        if name not in self.flags:
            raise ValueError(f"Unknown flag: {name}")
        self.flags[name] = enabled

    def get(self, name):
        return self.flags.get(name, False)

