class Permissions:
    READ = 'read'
    WRITE = 'write'

    def __init__(self):
        self.permissions = {
            'viewer': {self.READ},
            'editor': {self.READ, self.WRITE}
        }

    def allowed(self, role, action):
        if role not in self.permissions:
            return False
        return action in self.permissions[role]

class EventStore:
    def __init__(self):
        self._events = {}

    def record(self, user, value):
        if user not in self._events:
            self._events[user] = []
        self._events[user].append(value)

    def latest(self, user):
        if user in self._events:
            return self._events[user][-1]
        return None

